'use server';

/**
 * @fileOverview A flow that finds tourist attractions in a given city using the Google Maps Places API.
 * 
 * - findAttractions - A function that finds tourist attractions.
 * - findAttractionsFlow - The Genkit flow that orchestrates the attraction finding process.
 */

import { ai } from '@/ai/genkit';
import { z } from 'genkit';
import { Client } from '@googlemaps/google-maps-services-js';
import { FindAttractionsInputSchema, FindAttractionsOutputSchema, ApiAttractionSchema } from '@/lib/types';
import { PlacePhoto } from '@googlemaps/google-maps-services-js';

// Exporting the function that calls the flow
export async function findAttractions(input: z.infer<typeof FindAttractionsInputSchema>): Promise<z.infer<typeof FindAttractionsOutputSchema>> {
  return findAttractionsFlow(input);
}

// Initialize the Google Maps Client
const mapsClient = new Client({});

/**
 * Fetches a photo URL for a given photo reference.
 */
async function getPhotoUrl(photo: PlacePhoto): Promise<string | undefined> {
  if (!process.env.GOOGLE_MAPS_API_KEY) {
    return undefined;
  }
  // This is a simplified way to construct the URL.
  // In a real app, you might want to handle different size constraints.
  const baseUrl = 'https://maps.googleapis.com/maps/api/place/photo';
  const params = new URLSearchParams({
    maxwidth: '400',
    photoreference: photo.photo_reference,
    key: process.env.GOOGLE_MAPS_API_KEY,
  });
  return `${baseUrl}?${params.toString()}`;
}


// Define the Genkit flow
const findAttractionsFlow = ai.defineFlow(
  {
    name: 'findAttractionsFlow',
    inputSchema: FindAttractionsInputSchema,
    outputSchema: FindAttractionsOutputSchema,
  },
  async (input) => {

    if (!process.env.GOOGLE_MAPS_API_KEY) {
        console.error('GOOGLE_MAPS_API_KEY is not set.');
        return {
            attractions: [],
            error: 'API key for Google Maps is not configured. Please contact the administrator.'
        };
    }

    try {
      const query = `tourist attractions in ${input.city} ${input.category || ''}`;
      const response = await mapsClient.textSearch({
        params: {
          query: query,
          key: process.env.GOOGLE_MAPS_API_KEY!,
        },
      });

      if (response.data.results) {
         const attractionsWithPhotos = await Promise.all(
          response.data.results.map(async (place) => {
             const photoUrls = place.photos ? await Promise.all(
              place.photos.slice(0, 1).map(p => getPhotoUrl(p))
            ) : [];

            return {
              id: place.place_id,
              name: place.name,
              description: place.formatted_address, // Using address as a placeholder for description
              photos: photoUrls.filter((url): url is string => !!url),
              price_level: place.price_level,
              rating: place.rating,
              user_ratings_total: place.user_ratings_total,
              latitude: place.geometry?.location.lat,
              longitude: place.geometry?.location.lng,
            };
          })
        );
        return { attractions: attractionsWithPhotos.filter(a => a.id) };
      } else {
        return { attractions: [] };
      }
    } catch (e: any) {
      console.error('Error fetching attractions:', e.response?.data?.error_message || e.message);
      return {
        attractions: [],
        error: e.response?.data?.error_message || 'Failed to fetch attractions due to an unknown error.',
      };
    }
  }
);
