import { getCityByName } from "@/lib/data";
import Image from "next/image";
import { PlaceHolderImages } from "@/lib/placeholder-images";
import { type ApiAttraction, type City } from "@/lib/types";
import { Button } from "@/components/ui/button";
import { ArrowLeft, MessageCircle, Bot } from "lucide-react";
import Link from "next/link";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { StarRating } from "@/components/common/StarRating";
import { findAttractions } from "@/ai/flows/find-attractions";
import { ReviewForm } from "@/components/city/ReviewForm";
import { Reviews } from "@/components/city/Reviews";

type CityPageProps = {
  params: {
    cityName: string;
  };
};

// Helper function to capitalize city names for display
const capitalize = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

const getCityData = async (cityName: string): Promise<{ city: City; cityImage?: any; attractions: ApiAttraction[]; error?: string }> => {
  const decodedCityName = decodeURIComponent(cityName);
  
  // Try to find the city in our local data for hero image and description
  let city = getCityByName(decodedCityName);
  let cityImage;

  // If city is not in local data, create a placeholder object
  if (!city) {
    city = {
      id: decodedCityName.toLowerCase(),
      name: capitalize(decodedCityName),
      state: '', // State is unknown
      description: `Explore the best tourist attractions in ${capitalize(decodedCityName)}.`,
      image: 'hero', // Default hero image
    };
  }

  cityImage = PlaceHolderImages.find((img) => img.id === city!.image);

  // Always fetch attractions from the API
  const { attractions, error } = await findAttractions({ city: city.name });
  
  return { city, cityImage, attractions, error };
};

export default async function CityPage({ params }: CityPageProps) {
  const { city, cityImage, attractions, error } = await getCityData(params.cityName);

  return (
    <div className="flex flex-col">
      <section className="relative h-[40vh] w-full flex items-end justify-start text-white p-8">
        {cityImage && (
          <Image
            src={cityImage.imageUrl}
            alt={cityImage.description}
            fill
            className="object-cover"
            priority
            data-ai-hint={cityImage.imageHint}
          />
        )}
        <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/40 to-transparent" />
        <div className="relative z-10">
          <h1 className="text-5xl md:text-6xl font-bold font-headline tracking-tight">
            {city.name}
          </h1>
          <p className="max-w-3xl text-lg text-neutral-200 mt-2">
            {city.description}
          </p>
        </div>
      </section>

      <section className="container mx-auto px-4 py-12">
        <Button asChild variant="outline" className="mb-8">
           <Link href="/">
                <ArrowLeft className="mr-2"/> Go Back Home
            </Link>
        </Button>

        {error && (
            <div className="text-center py-16 bg-destructive/10 border border-destructive/20 rounded-lg">
                <h2 className="text-2xl font-semibold text-destructive">Could Not Load Attractions</h2>
                <p className="mt-2 text-muted-foreground">There was a problem fetching data from the Google Places API.</p>
                <p className="mt-2 text-sm text-muted-foreground">Reason: {error}</p>
                <p className="mt-4 text-xs text-muted-foreground">Please ensure the API key is correct and that the Google Places API is enabled and has billing configured in your Google Cloud project.</p>
            </div>
        )}
        
        {!error && attractions.length > 0 ? (
          <Accordion type="single" collapsible className="w-full" defaultValue="item-0">
            {attractions.map((attraction, index) => (
              attraction.id && (
              <AccordionItem key={attraction.id} value={`item-${index}`}>
                <AccordionTrigger className="text-xl font-headline hover:no-underline">
                  <div className="flex flex-col text-left">
                    {attraction.name}
                    {attraction.rating && (
                       <div className="flex items-center gap-2 text-sm text-muted-foreground font-normal">
                          <StarRating rating={attraction.rating} />
                          <span>({attraction.user_ratings_total} reviews)</span>
                       </div>
                    )}
                  </div>
                </AccordionTrigger>
                <AccordionContent>
                  <div className="grid md:grid-cols-2 gap-6 items-start">
                      <div>
                          <p className="mb-4 text-muted-foreground">{attraction.description || 'No description available.'}</p>
                           {attraction.latitude && attraction.longitude && (
                              <Button asChild variant="secondary">
                                  <a
                                      href={`https://www.google.com/maps/search/?api=1&query=${attraction.latitude},${attraction.longitude}`}
                                      target="_blank"
                                      rel="noopener noreferrer"
                                  >
                                      View on Map
                                  </a>
                              </Button>
                           )}
                      </div>
                       <div className="flex flex-col gap-4">
                          {attraction.photos?.map((photoUrl, idx) => (
                              <Image key={idx} src={photoUrl} alt={attraction.name || 'Attraction'} width={400} height={300} className="rounded-lg object-cover w-full" data-ai-hint="tourist attraction" />
                          ))}
                          {!attraction.photos?.length && (
                             <div className="w-full aspect-[4/3] bg-muted rounded-lg flex items-center justify-center">
                                <p className="text-muted-foreground">No Image Available</p>
                             </div>
                          )}
                      </div>
                  </div>
                   {/* Reviews section can be adapted to use API reviews or our own DB */}
                   {attraction.id && <Reviews attractionId={attraction.id} />}
                </AccordionContent>
              </AccordionItem>
              )
            ))}
          </Accordion>
        ) : !error && (
          <div className="text-center py-16">
            <h2 className="text-2xl font-semibold text-muted-foreground">No attractions found for this city yet.</h2>
            <p className="mt-2 text-muted-foreground">Check back later for updates!</p>
          </div>
        )}

      </section>
    </div>
  );
}
